#include <stddef.h>
#include <stdint.h>
int64_t permutation_cipher(const int64_t*v,size_t n){if(!v||n<2||n>74||v[0]<0||v[0]>64)return -1;size_t len=(size_t)v[0];if(n<len+2)return -1;size_t kpos=len+1;if(v[kpos]<1||v[kpos]>8||n!=kpos+(size_t)v[kpos]+1)return -1;size_t k=(size_t)v[kpos];int seen[8]={0};for(size_t i=0;i<k;i++){int64_t x=v[kpos+1+i];if(x<1||x>(int64_t)k||seen[x-1])return -1;seen[x-1]=1;}char text[128],out[128];size_t m=0;for(size_t i=0;i<len;i++){if(v[i+1]<0||v[i+1]>127)return -1;int c=(int)v[i+1];if(c==32||c==9||c==10||c==11||c==12||c==13)continue;if(c>='a'&&c<='z')c-=32;text[m++]=(char)c;}while(m%k)text[m++]='X';size_t q=0;for(size_t b=0;b<m;b+=k)for(size_t j=0;j<k;j++)out[q++]=text[b+(size_t)v[kpos+1+j]-1];uint64_t h=0;for(size_t i=0;i<q;i++)h=(h*257u+(unsigned char)out[i])%1000000007u;return (int64_t)h;}
